<?php $rows=$pdo->query('SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 500')->fetchAll(); ?>
<div class="card panel"><h3>Audit Trail Aktivitas Pengguna</h3><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Entitas</th><th>ID</th><th>Deskripsi</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_name']??'Sistem')?></td><td><span class="status st-blue"><?=e($r['action'])?></span></td><td><?=e($r['entity_type'])?></td><td><?=e((string)$r['entity_id'])?></td><td><?=e($r['description'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div>
